function bindWorkspaceCoverPosition(element,item){if(!element)return;const image=element.querySelector("img");if(!image)return;element.ondblclick=event=>{event.preventDefault();element.classList.add("repositioning")};element.onpointerdown=event=>{if(!element.classList.contains("repositioning"))return;event.preventDefault();const startX=event.clientX,startY=event.clientY,startPositionX=Number.isFinite(Number(item.coverPositionX))?Number(item.coverPositionX):50,startPositionY=Number.isFinite(Number(item.coverPositionY))?Number(item.coverPositionY):Number.isFinite(Number(item.coverPosition))?Number(item.coverPosition):50,width=Math.max(1,element.clientWidth),height=Math.max(1,element.clientHeight);element.setPointerCapture?.(event.pointerId);const move=moveEvent=>{item.coverPositionX=Math.max(0,Math.min(100,startPositionX+(moveEvent.clientX-startX)/width*100));item.coverPositionY=Math.max(0,Math.min(100,startPositionY+(moveEvent.clientY-startY)/height*100));image.style.objectPosition=`${item.coverPositionX}% ${item.coverPositionY}%`};const up=()=>{element.removeEventListener("pointermove",move);element.removeEventListener("pointerup",up);element.removeEventListener("pointercancel",up);element.classList.remove("repositioning");persist()};element.addEventListener("pointermove",move);element.addEventListener("pointerup",up);element.addEventListener("pointercancel",up)}}
function workspaces(scope=activeWorkspaceScope){if(scope==="home")return config.getHomePages?.()||[];return scope==="private"?(config.getPrivateWorkspaces?.()||[]):(config.getWorkspaces?.()||[])}
function allWorkspaces(){return[...workspaces("shared"),...workspaces("private"),...workspaces("home")]}
function activeWorkspace(){return workspaces().find(item=>item.id===activeWorkspaceId)||null}
function baseColumns(kind){
if(kind==="list")return[{id:uid(),name:"Nombre",type:"text",width:360}];
if(kind==="combined-list")return[{id:uid(),name:"Nombre",type:"text",width:260},{id:uid(),name:"Estado",type:"status",width:150,statusOptions:statusOptions()}];
return[{id:uid(),name:"Detalle",type:"text",width:260},{id:uid(),name:"Fecha",type:"date",width:150,dateFormat:"dd/mm/yyyy"},{id:uid(),name:kind.includes("pages")?"Total":"Valor",type:"currency",width:180,autoPageTotal:kind.includes("pages")}];
}
function statusOptions(){return[{label:"Pendiente",color:"#9b9a97"},{label:"Parcial",color:"#dfab01"},{label:"Completo",color:"#448361"}]}
function defaultTableView(){return{search:"",filterColumn:"",filterValue:"",sortColumn:"",sortDirection:"asc"}}
function tableView(table){table.viewState={...defaultTableView(),...(table.viewState||{})};return table.viewState}
function workspaceRowsInView(table){const view=tableView(table),source=table._timelinePeriod?timelineRowsForPeriod(table,table._timelinePeriod):table.rows;let rows=source.filter(row=>{const matchesSearch=!view.search||table.columns.some(column=>String(row[column.id]??"").toLocaleLowerCase("es").includes(view.search.toLocaleLowerCase("es")));const matchesFilter=!view.filterValue||!view.filterColumn||String(row[view.filterColumn]??"").toLocaleLowerCase("es").includes(view.filterValue.toLocaleLowerCase("es"));return matchesSearch&&matchesFilter});if(view.sortColumn)rows=[...rows].sort((a,b)=>String(a[view.sortColumn]??"").localeCompare(String(b[view.sortColumn]??""),"es",{numeric:true,sensitivity:"base"})*(view.sortDirection==="desc"?-1:1));return rows}
function defaultPageOptions(){return{wide:false,selection:false,focus:false}}
function pageOptions(page){page.options={...defaultPageOptions(),...(page.options||{})};return page.options}
function newTable(kind,index=0){return{id:uid(),name:index?`Pesta\u00f1a ${index+1}`:"Vista principal",tabIcon:"img/pagev.png",columns:baseColumns(kind),rows:[],viewState:defaultTableView()}}
function newDirectoryItem(index=0){return{id:uid(),name:`Elemento ${index+1}`,recordId:"",attribute:"",relationshipStart:"",address:"",status:"Activo",area:""}}
function newDirectoryTab(index=0){const item=newDirectoryItem();return{id:uid(),name:index?`Pesta\u00f1a ${index+1}`:"Directorio",items:[item],activeItemId:item.id}}
function normalize(){
allWorkspaces().forEach(page=>{
page.id||=uid();page.title||="Nueva Pagina";page.emoji||="\uD83D\uDCC4";page.description??="Escribe una descripci\u00f3n..";page.createdBy||=config.getCurrentUserId?.()||null;pageOptions(page);page.blocks=Array.isArray(page.blocks)?page.blocks:[];
page.blocks.forEach(block=>{if(block.kind==="timeline-panel"&&block.name==="TimeLapse")block.name="Calendario"});
page.blocks.forEach(block=>{block.id||=uid();block.name||=blockTypes.find(type=>type[0]===block.kind)?.[1]||"Datos";if(["separator","meter","chart"].includes(block.kind)){if(block.kind==="meter")block.meterObjective=Math.max(0,numericValue(block.meterObjective||100));if(block.kind==="chart"){block.chartType||="vertical";block.chartSum=Boolean(block.chartSum);block.chartHideDataLabels=Boolean(block.chartHideDataLabels)}return}if(["directory","tabbed-directory"].includes(block.kind)){block.directoryTabs=Array.isArray(block.directoryTabs)&&block.directoryTabs.length?block.directoryTabs:[newDirectoryTab()];block.directoryTabs.forEach((tab,index)=>{tab.id||=uid();tab.name||=`Pesta\u00f1a ${index+1}`;tab.items=Array.isArray(tab.items)?tab.items:[];tab.items.forEach((item,itemIndex)=>{item.id||=uid();item.name||=`Elemento ${itemIndex+1}`;item.status=item.status==="Inactivo"?"Inactivo":"Activo"});tab.activeItemId=tab.items.some(item=>item.id===tab.activeItemId)?tab.activeItemId:tab.items[0]?.id||null});block.activeDirectoryTabId=block.directoryTabs.some(tab=>tab.id===block.activeDirectoryTabId)?block.activeDirectoryTabId:block.directoryTabs[0].id;return}if(block.kind.includes("list")){block.items=Array.isArray(block.items)?block.items:[];return}block.tables=Array.isArray(block.tables)&&block.tables.length?block.tables:[newTable(block.kind)];block.activeTableId=block.tables.some(table=>table.id===block.activeTableId)?block.activeTableId:block.tables[0].id;block.tables.forEach((table,index)=>{table.id||=uid();table.name||=`Pesta\u00f1a ${index+1}`;table.tabIcon||="img/pagev.png";table.columns=Array.isArray(table.columns)&&table.columns.length?table.columns:baseColumns(block.kind);table.rows=Array.isArray(table.rows)?table.rows:[];tableView(table);table.columns.forEach(column=>{column.id||=uid();column.name||="Columna";column.type||="text";column.width||=160;if(column.type==="status"&&!column.statusOptions)column.statusOptions=statusOptions();if(["select","multiselect"].includes(column.type)&&!column.options)column.options=[]})})});
});
allWorkspaces().forEach(page=>page.blocks.forEach(block=>{if(block.kind==="meter"&&block.meterObjectiveEmpty)block.meterObjective=""}));
}
