function openWorkspaceMenu(button,anchor){
closePopups();const scope=button.dataset.workspaceScope||"shared",pages=workspaces(scope),page=pages.find(item=>item.id===button.dataset.customWorkspaceId);if(!page)return;
const menu=document.createElement("div");menu.className="workspace-floating-menu workspace-page-options";menu.innerHTML=`<button data-action="rename">✎ Renombrar</button><button data-action="duplicate">⧉ Duplicar</button><button class="danger" data-action="delete">× Eliminar</button>`;document.body.appendChild(menu);positionMenu(menu,anchor);
menu.addEventListener("click",event=>{const action=event.target.closest("button")?.dataset.action;if(action==="rename"){showWorkspace(page.id,scope);setTimeout(()=>document.getElementById("customWorkspaceTitle")?.select(),20)}if(action==="duplicate"){const copy=structuredClone(page);copy.id=uid();copy.title+=` (copia)`;copy.blocks.forEach(block=>{block.id=uid();block.tables?.forEach(table=>{table.id=uid()});block.directoryTabs?.forEach(tab=>{tab.id=uid();tab.items.forEach(item=>item.id=uid());tab.activeItemId=tab.items[0]?.id||null});if(block.directoryTabs?.length)block.activeDirectoryTabId=block.directoryTabs[0].id});pages.push(copy);persist();renderLinks()}if(action==="delete"){const index=pages.findIndex(item=>item.id===page.id);pages.splice(index,1);persist();renderLinks();if(activeWorkspaceId===page.id&&activeWorkspaceScope===scope){activeWorkspaceId=null;document.querySelector('[data-workspace-view="greeting"]')?.click()}}closePopups()});
}
