function workspaceTimelinePeriods(year,view){const pad=value=>String(value).padStart(2,"0");if(view==="monthly")return Array.from({length:12},(_,month)=>{const date=`${year}-${pad(month+1)}-01`,end=`${year}-${pad(month+2)}-01`,safeEnd=month===11?`${year+1}-01-01`:end,label=new Intl.DateTimeFormat("es",{month:"short"}).format(new Date(`${date}T12:00:00`));return{key:pad(month+1),date,end:safeEnd,label,title:new Intl.DateTimeFormat("es",{month:"long",year:"numeric"}).format(new Date(`${date}T12:00:00`))}});const days=[];for(let date=new Date(year,0,1);date.getFullYear()===year;date.setDate(date.getDate()+1)){const iso=`${year}-${pad(date.getMonth()+1)}-${pad(date.getDate())}`,next=new Date(date);next.setDate(next.getDate()+1);const end=`${next.getFullYear()}-${pad(next.getMonth()+1)}-${pad(next.getDate())}`;days.push({key:iso,date:iso,end,label:new Intl.DateTimeFormat("es",{day:"2-digit",month:"short"}).format(date),title:new Intl.DateTimeFormat("es",{weekday:"long",day:"2-digit",month:"long",year:"numeric"}).format(date)})}if(view==="daily")return days;const weeks=[];for(let index=0;index<days.length;index+=7){const first=days[index],last=days[Math.min(index+6,days.length-1)];weeks.push({key:`w${weeks.length+1}`,date:first.date,end:last.end,label:`S${weeks.length+1}`,title:`${first.label} \u2014 ${last.label}`})}return weeks}
